import Foundation
import LocalAuthentication
import Security
#if os(macOS)
import AppKit
#else
import UIKit
#endif
import GiroCrabCore

/// Keeps the 32-byte SQLCipher master key in the Apple Keychain, protected by
/// Face ID / Touch ID (with device passcode fallback).
///
/// * First launch: a random key is generated by the Rust core and stored with
///   `SecAccessControl(.userPresence)` in the data-protection keychain
///   (`kSecAttrAccessibleWhenUnlockedThisDeviceOnly`, never synced to iCloud).
/// * Every unlock: one biometric prompt; the authenticated `LAContext` is
///   handed to the keychain query so the user is asked only once.
/// * Unsigned/ad-hoc macOS builds cannot use the data-protection keychain
///   (errSecMissingEntitlement). Then the key goes into the login keychain and
///   the biometric check is enforced by the app before reading it.
public final class VaultKeyManager: @unchecked Sendable {
    public enum KeyError: LocalizedError {
        case biometryUnavailable(String)
        case cancelled
        case keychain(OSStatus)
        /// No key in the keychain although a vault file exists: never create a
        /// new one then (a delayed iCloud Keychain sync would be shadowed).
        case keyMissing
        /// Writing the new key failed and writing the previous one back too.
        case keyNotRestored(OSStatus)

        public var errorDescription: String? {
            switch self {
            case .biometryUnavailable(let why): return String(localized: "Face ID / Touch ID ist nicht verfügbar: \(why)")
            case .cancelled: return String(localized: "Entsperren abgebrochen.")
            case .keyMissing:
                return String(localized: "Der Schlüssel für den vorhandenen Tresor fehlt im Schlüsselbund. Wenn Sie den iCloud-Schlüsselbund nutzen, warten Sie, bis er synchronisiert ist, und versuchen Sie es erneut. Es wurde kein neuer Schlüssel angelegt.")
            case .keyNotRestored(let status):
                return String(localized: "Der Tresor-Schlüssel konnte nicht im Schlüsselbund gespeichert werden (Fehler \(status)). Der Tresor bleibt bis zum Beenden geöffnet – bitte GiroCrab nicht beenden, den Schlüsselbund prüfen (Schlüsselbundverwaltung) und den Vorgang wiederholen.")
            case .keychain(let status):
                let msg = SecCopyErrorMessageString(status, nil) as String? ?? "unknown"
                return String(localized: "Schlüsselbund-Fehler \(status): \(msg)")
            }
        }
    }

    public static let shared = VaultKeyManager()

    private let service = "de.girocrab.vault"
    private let account = "sqlcipher-master-key"

    /// Opt-in: store the key as `kSecAttrSynchronizable` so iCloud Keychain shares
    /// it between Mac and iOS. Synchronizable items cannot carry a biometric
    /// access-control flag, so the app enforces the LAContext check itself.
    public static let syncDefaultsKey = "girocrab.keySyncICloudKeychain"
    public var syncViaICloudKeychain: Bool {
        get { UserDefaults.standard.bool(forKey: Self.syncDefaultsKey) }
        set { UserDefaults.standard.set(newValue, forKey: Self.syncDefaultsKey) }
    }

    private static func envFlag(_ name: String) -> Bool {
        ProcessInfo.processInfo.environment[name].map { ["1", "true", "yes"].contains($0.lowercased()) } ?? false
    }

    /// Developer bypass: with `GIROCRAB_NO_KEYCHAIN=1` or `GIROCRAB_DEMO_SEED=1` the Keychain
    /// is never touched (ad-hoc `swift run` binaries get a new CDHash per build, so the
    /// "access key de.girocrab.vault" password prompt would reappear every time).
    /// The vault then uses a separate file (`AppModel.vaultURL`) with a fixed throw-away key,
    /// so the real vault is neither opened nor modified.
    public static var keychainBypassed: Bool {
        envFlag("GIROCRAB_NO_KEYCHAIN") || envFlag("GIROCRAB_DEMO_SEED")
    }

    /// In bypass mode the real Touch ID check still runs, except for demo seed runs
    /// (no prompts) or when the user switched "require Touch ID" off.
    static var biometricsPromptInBypass: Bool {
        !envFlag("GIROCRAB_DEMO_SEED") && shared.requireBiometrics
    }

    private static let devKey = Data(repeating: 0x42, count: 32)

    /// Whether unlocking asks for Touch ID / Face ID. Only macOS can switch it off
    /// (the key is then stored without a biometric access flag); iOS always asks.
    public static let requireBiometricsDefaultsKey = "girocrab.requireBiometrics"
    public var requireBiometrics: Bool {
        #if os(macOS)
        UserDefaults.standard.object(forKey: Self.requireBiometricsDefaultsKey) as? Bool ?? true
        #else
        true
        #endif
    }

    /// Re-stores the existing key with or without the biometric requirement.
    public func setRequireBiometrics(_ enabled: Bool) async throws {
        if Self.keychainBypassed {
            // Dev bypass: no stored key to re-protect, only the preference changes.
            UserDefaults.standard.set(enabled, forKey: Self.requireBiometricsDefaultsKey)
            return
        }
        var key = try await unlock()
        defer { key.resetBytes(in: 0..<key.count) }
        let previous = requireBiometrics
        UserDefaults.standard.set(enabled, forKey: Self.requireBiometricsDefaultsKey)
        do {
            try replaceStoredKey(with: key, previous: key, syncing: syncViaICloudKeychain)
        } catch {
            UserDefaults.standard.set(previous, forKey: Self.requireBiometricsDefaultsKey)
            throw error
        }
    }

    /// Re-stores the existing key with the chosen synchronizable setting.
    public func setICloudKeychainSync(_ enabled: Bool) async throws {
        var key = try await unlock()
        defer { key.resetBytes(in: 0..<key.count) }
        try replaceStoredKey(with: key, previous: key, syncing: enabled)
    }

    /// True if the last `unlock()` generated a brand-new key (none was in the keychain).
    public private(set) var lastUnlockCreatedKey = false

    public init() {}

    /// Human name of the available biometry ("Touch ID", "Face ID", "Optic ID", "Passcode").
    public var biometryName: String {
        let ctx = LAContext()
        _ = ctx.canEvaluatePolicy(.deviceOwnerAuthenticationWithBiometrics, error: nil)
        switch ctx.biometryType {
        case .faceID: return "Face ID"
        case .touchID: return "Touch ID"
        case .opticID: return "Optic ID"
        default: return String(localized: "Gerätecode")
        }
    }

    public var biometrySymbol: String {
        let ctx = LAContext()
        _ = ctx.canEvaluatePolicy(.deviceOwnerAuthenticationWithBiometrics, error: nil)
        switch ctx.biometryType {
        case .faceID: return "faceid"
        case .touchID: return "touchid"
        case .opticID: return "opticid"
        default: return "lock.fill"
        }
    }

    /// Authenticates the user and returns the master key. A new key is created
    /// only with `allowCreate` (first start, no vault file yet); otherwise a
    /// missing key is `KeyError.keyMissing`.
    public func unlock(reason: String = String(localized: "GiroCrab-Tresor entsperren"), allowCreate: Bool = false) async throws -> Data {
        let context = LAContext()
        context.localizedCancelTitle = String(localized: "Abbrechen")
        if Self.keychainBypassed {
            // Dev: never touch the Keychain. Touch ID stays active (unless it is switched
            // off or this is a demo seed run); afterwards the throw-away key is returned.
            lastUnlockCreatedKey = false
            if Self.biometricsPromptInBypass { try await authenticate(context: context, reason: reason) }
            return Self.devKey
        }
        if !requireBiometrics {
            // No Touch ID prompt: the key sits in the keychain without a biometric flag.
            if let key = try read(context: context) {
                lastUnlockCreatedKey = false
                return key
            }
            guard allowCreate else { throw KeyError.keyMissing }
            let key = GiroCrabCore.generateMasterKey()
            lastUnlockCreatedKey = true
            try store(key)
            return key
        }
        try await authenticate(context: context, reason: reason)
        if let key = try read(context: context) {
            lastUnlockCreatedKey = false
            return key
        }
        guard allowCreate else { throw KeyError.keyMissing }
        let key = GiroCrabCore.generateMasterKey()
        lastUnlockCreatedKey = true
        try store(key)
        return key
    }

    /// Runs the real `LAContext` check (Touch ID / passcode).
    private func authenticate(context: LAContext, reason: String) async throws {
        var err: NSError?
        guard context.canEvaluatePolicy(.deviceOwnerAuthentication, error: &err) else {
            throw KeyError.biometryUnavailable(err?.localizedDescription ?? String(localized: "kein Gerätecode eingerichtet"))
        }
        #if os(macOS)
        await Self.bringAppToFront()
        #endif
        do {
            let ok = try await context.evaluatePolicy(.deviceOwnerAuthentication, localizedReason: reason)
            if !ok { throw KeyError.cancelled }
        } catch let e as LAError where e.code == .userCancel || e.code == .appCancel || e.code == .systemCancel {
            throw KeyError.cancelled
        }
    }

    #if os(macOS)
    /// The Touch ID sheet only receives sensor focus when the app is frontmost;
    /// right after launch (`swift run`) it often is not yet, and the finger is
    /// ignored until the user clicks the dialog.
    @MainActor
    private static func bringAppToFront() async {
        let app = NSApplication.shared
        if app.activationPolicy() != .regular { app.setActivationPolicy(.regular) }
        guard !app.isActive else { return }
        app.activate(ignoringOtherApps: true)
        try? await Task.sleep(for: .milliseconds(80))
    }
    #endif

    /// Key as Base64 for manual transfer to another device (after authentication).
    public func exportKeyBase64() async throws -> String {
        try await unlock().base64EncodedString()
    }

    /// Replaces the stored key with one pasted from another device (Base64 or hex).
    public static func parseKey(_ text: String) throws -> Data {
        let t = text.trimmingCharacters(in: .whitespacesAndNewlines)
        var data = Data(base64Encoded: t)
        if data == nil || data!.count != 32, t.count == 64 {
            var bytes = [UInt8](); var i = t.startIndex
            while i < t.endIndex {
                let n = t.index(i, offsetBy: 2)
                guard let b = UInt8(t[i..<n], radix: 16) else { bytes = []; break }
                bytes.append(b); i = n
            }
            if bytes.count == 32 { data = Data(bytes) }
        }
        guard let key = data, key.count == 32 else {
            throw NSError(domain: "VaultKey", code: 1, userInfo: [NSLocalizedDescriptionKey: String(localized: "Ungültiger Schlüssel (erwartet 32 Byte, Base64 oder Hex).")])
        }
        return key
    }

    /// Replaces the stored key with `key`. `previous` is the key stored now:
    /// if the new one cannot be written, `previous` is written back, so the
    /// keychain never ends up empty.
    public func importKey(_ key: Data, replacing previous: Data) throws {
        try replaceStoredKey(with: key, previous: previous, syncing: syncViaICloudKeychain)
    }

    /// Writes `key` in the requested storage mode. A keychain item cannot change
    /// its access control or synchronizable flag in place (`SecItemUpdate`), and
    /// both modes share service/account, so the old item has to go first – but
    /// on any failure the previous key and mode are written back before the
    /// error is reported. Only if even that fails, `keyNotRestored` says so.
    private func replaceStoredKey(with key: Data, previous: Data, syncing: Bool) throws {
        let previousMode = syncViaICloudKeychain
        destroyKey()
        syncViaICloudKeychain = syncing
        do {
            try store(key)
        } catch {
            syncViaICloudKeychain = previousMode
            do {
                try store(previous)
            } catch let restoreError as KeyError {
                if case .keychain(let status) = restoreError { throw KeyError.keyNotRestored(status) }
                throw restoreError
            }
            throw error
        }
    }

    /// Clipboard helper for manual key transfer; cleared after 60 s.
    @MainActor public static func copyToPasteboard(_ text: String) {
        #if os(macOS)
        let pb = NSPasteboard.general
        pb.clearContents()
        pb.setString(text, forType: .string)
        let count = pb.changeCount
        DispatchQueue.main.asyncAfter(deadline: .now() + 60) {
            if NSPasteboard.general.changeCount == count { NSPasteboard.general.clearContents() }
        }
        #else
        UIPasteboard.general.setItems([[UIPasteboard.typeAutomatic: text]], options: [.expirationDate: Date().addingTimeInterval(60), .localOnly: true])
        #endif
    }

    /// Removes the key. The encrypted vault becomes unreadable!
    public func destroyKey() {
        for dp in [true, false] {
            var q = baseQuery()
            q[kSecUseDataProtectionKeychain as String] = dp
            q[kSecAttrSynchronizable as String] = kSecAttrSynchronizableAny
            SecItemDelete(q as CFDictionary)
        }
    }

    // MARK: - Keychain

    private func baseQuery() -> [String: Any] {
        [
            kSecClass as String: kSecClassGenericPassword,
            kSecAttrService as String: service,
            kSecAttrAccount as String: account,
        ]
    }

    private func read(context: LAContext) throws -> Data? {
        for dataProtection in [true, false] {
            var q = baseQuery()
            q[kSecReturnData as String] = true
            q[kSecMatchLimit as String] = kSecMatchLimitOne
            q[kSecUseAuthenticationContext as String] = context
            q[kSecUseDataProtectionKeychain as String] = dataProtection
            q[kSecAttrSynchronizable as String] = kSecAttrSynchronizableAny
            var out: CFTypeRef?
            let status = SecItemCopyMatching(q as CFDictionary, &out)
            switch status {
            case errSecSuccess:
                return out as? Data
            case errSecItemNotFound, errSecMissingEntitlement:
                continue
            case errSecUserCanceled, errSecAuthFailed:
                throw KeyError.cancelled
            default:
                throw KeyError.keychain(status)
            }
        }
        return nil
    }

    private func store(_ key: Data) throws {
        if syncViaICloudKeychain {
            var q = baseQuery()
            q[kSecValueData as String] = key
            q[kSecAttrAccessible as String] = kSecAttrAccessibleWhenUnlocked
            q[kSecUseDataProtectionKeychain as String] = true
            q[kSecAttrSynchronizable as String] = true
            let status = SecItemAdd(q as CFDictionary, nil)
            if status == errSecSuccess { return }
            if status != errSecMissingEntitlement { throw KeyError.keychain(status) }
        }
        var acError: Unmanaged<CFError>?
        let flags: SecAccessControlCreateFlags = requireBiometrics ? .userPresence : []
        if let access = SecAccessControlCreateWithFlags(nil, kSecAttrAccessibleWhenUnlockedThisDeviceOnly, flags, &acError) {
            var q = baseQuery()
            q[kSecValueData as String] = key
            q[kSecAttrAccessControl as String] = access
            q[kSecUseDataProtectionKeychain as String] = true
            q[kSecAttrSynchronizable as String] = false
            let status = SecItemAdd(q as CFDictionary, nil)
            if status == errSecSuccess { return }
            if status != errSecMissingEntitlement && status != errSecDuplicateItem {
                throw KeyError.keychain(status)
            }
        }
        // Fallback for unsigned macOS builds: login keychain, gated by LAContext above.
        var q = baseQuery()
        q[kSecValueData as String] = key
        q[kSecAttrAccessible as String] = kSecAttrAccessibleWhenUnlockedThisDeviceOnly
        q[kSecUseDataProtectionKeychain as String] = false
        let status = SecItemAdd(q as CFDictionary, nil)
        guard status == errSecSuccess else { throw KeyError.keychain(status) }
    }
}
